 function picker(index){pickSlot=index;pickFaction=state.mode==='story'?state.storyFaction:state.libraryFaction;renderPicker();}
 function renderPicker(){const role=pickSlot===5?'軍師':pickSlot===6?'運糧':'武將位置 '+(pickSlot+1);modal('選擇'+role,`<p class="small">${pickSlot===5?'智力65以上才能擔任軍師。計策值上限＝10＋⌊(軍師永久等級－1)×智力÷100⌋。目前永久升級尚未接入，按1級計算；升級或換場不自動補滿。':pickSlot===6?'比較統率與魅力，開局軍糧換算尚未定案。':'同名武將只能配置在一格。'} 只可選用已解鎖的武將；其他陣營仍可瀏覽。</p>${factionTabs(pickFaction,'pickFaction')}<div class="collection">${roster.filter(p=>p.faction===pickFaction).map(p=>officerButton(p,true)).join('')}</div>`);}
