 function renderJourney(){if(state.mode==='battle'){$('content').innerHTML=`<span class="eyebrow">對戰出征</span><h2>五方群雄，組成一隊</h2><p>五陣營皆可瀏覽，可選用已解鎖的武將。候選名額合併計算，解鎖與劇情共用，等級及星級各自獨立。</p>${btn('<strong>編輯七格隊伍</strong><small>五將・軍師・運糧</small>','team','','primary')}<div class="panel"><h3>對戰入口</h3><p>配對形式與實際對戰尚未接入。</p><button disabled>進入對戰 · 尚未開放</button></div>`;return;}$('content').innerHTML=`${taskBack()}<span class="eyebrow">劇情出征</span><h2>選擇一段征途</h2><p>目前開放蜀國序章「桃園起兵」，其他陣營與後續篇章將逐步開放。</p><div class="journey-grid">${factions.filter(f=>f!=='特殊').map(f=>btn(`<strong>${f}</strong><small>${f==='蜀'?(state.storyFaction===f?'目前路線 · 已開放':'桃園起兵 · 已開放'):'後續開放'}</small>`,'storyFaction',`data-faction="${f}"`)).join('')}</div>${state.storyFaction==='蜀'?`<div class="panel"><h3>蜀 · 桃園起兵</h3><p>從劉備家出發，探訪村莊、村東、村西與村長家，結識同伴、尋找失物，再出村掃蕩賊寇。</p>${btn('進入桃園起兵','enterStory','','primary')}${btn('整頓軍備','team','','confirm')}<p class="small">進度自動保存，再次進入會接續上次旅程。</p></div>`:state.storyFaction?`<div class="panel"><h3>${state.storyFaction} · 後續開放</h3><p>這條劇情路線尚未開放，請先體驗蜀國的桃園起兵。</p><button disabled>尚未開放</button></div>`:''}`;}
 function chestItems(items){return items.map(x=>x.kind==='letter'?'青色字卡「'+esc(x.name)+'」×'+x.count:esc(x.name)+'碎片（'+x.quality+'）×'+x.count).join('、');}
