 function renderShop(){const bag=ChestSystem.init(state);$('content').innerHTML='<h2>寶箱</h2><div class="boxlist">'+Object.entries(ChestSystem.tiers).map(([id,t])=>btn('<span class="box-icon">匣</span><strong>'+t.name+'</strong><p>持有 '+(bag.boxes[id]||0)+' 箱</p><small>'+(id==='4'?'尚未開放':t.currency?t.price+(t.currency==='coins'?' 金幣':' 鑽石'):'任務／關卡取得')+'</small>','box','data-tier="'+id+'"')).join('')+'</div>'+(!state.storyFaction&&state.mode==='story'?btn('選擇劇情陣營','journey','','wide'):'')+'<h3 class="shop-section-title">最近取得</h3><div class="chest-history" tabindex="0" role="region" aria-label="最近取得紀錄">'+bag.history.slice(0,15).map(r=>'<div class="panel">'+(r.type==='open'?ChestSystem.tiers[r.tier].name+'：'+(r.items?chestItems(r.items):'舊版通用碎片紀錄（已停用兌換）'):'解鎖 '+esc(r.name)+' · 名字字卡：'+r.letters.map(esc).join('、'))+'<br><small>'+esc(new Date(r.at).toLocaleString('zh-TW'))+'</small></div>').join('')+'</div>';}
 function boxDetails(tier){const t=ChestSystem.tiers[tier];if(!t)return;const bag=ChestSystem.init(state),wallet=window.SharedWallet.init(state),p=ChestSystem.pool(state,tier),can=p.letters.length&&p.rates.some(n=>n>0);modal(t.name,'<p>共用寶箱 · 五陣營字卡與武將碎片。</p><p>每箱'+ChestSystem.draws+'次獨立抽選：單字卡50%、武將專屬碎片50%。每次取得一張字卡或一片指定武將碎片；可能各一個、兩張字卡或兩片碎片。</p><p>抽中碎片後的武將品質機率：'+p.rates.map((n,i)=>n?ChestSystem.colors[i]+' '+Number(n.toFixed(2))+'%':'').filter(Boolean).join(' · ')+'</p><p>同品質內每名武將等機率，已持有武將仍可抽到。單字池按陣營名字去重，各字等機率，字卡皆青色。</p><p class="small">若陣營某品質沒有武將，該品質不抽取，其餘比例按原權重換算。重複字保留張數與原養成。</p>'+(tier===4?'<p>四級寶箱尚未開放，不會扣款。</p>':btn('開啟持有寶箱（剩 '+(bag.boxes[tier]||0)+'）','openBox','data-tier="'+tier+'" data-source="stock" '+(can&&bag.boxes[tier]>0?'':'disabled'),'wide')+(t.currency?btn('花費 '+t.price+(t.currency==='coins'?' 金幣':' 鑽石')+'，購買並開啟','openBox','data-tier="'+tier+'" data-source="buy" '+(can&&wallet[t.currency]>=t.price?'':'disabled'),'wide confirm'):'<p>需先取得任務／關卡寶箱。</p>')));}
 function fragmentDetails(name){const p=roster.find(p=>p.name===name);if(!p)return;const bag=ChestSystem.init(state),n=bag.officerFragments[name]||0,missing=[...new Set(name)].filter(ch=>!state.unlocks[state.mode].letters.includes(ch));modal(name+' · 專屬碎片','<p>持有 '+n+' 片，只用於 '+esc(name)+' 的升星養成；升星操作尚未接入。</p><p>集齊名字字卡會自動解鎖，不扣字卡、不扣碎片。</p><p>'+(unlocked(name)?'武將已解鎖。':'尚缺字卡：'+missing.map(esc).join('、'))+'</p>');}
 function chestTransaction(action,args){try{const next=JSON.parse(localStorage.getItem(key)||JSON.stringify(state));next.mode=state.mode;next.storyFaction=state.storyFaction;next.unlocks??=state.unlocks;const receipt=action==='open'?ChestSystem.open(next,args.tier,args.source):ChestSystem.unlock(next,args.name);next.page='shop';ProgressRewards.sync(next);localStorage.setItem(key,JSON.stringify(next));state=next;page='shop';close();render();if(action==='open')modal('開箱結果',chestResult(receipt.items));else modal('武將已解鎖','<h3>'+esc(receipt.name)+'</h3><p>名字字卡：'+receipt.letters.map(esc).join('、')+'。已可於本模式編入隊伍。</p>'+btn('前往字卡庫','ownedLibrary','','confirm'));}catch(e){toast('未完成：'+e.message+'。本次未入帳。');}}
