  if(rewardTab==='achievement'){const levels=playerAchievements().filter(x=>x.id.startsWith('player-level-'));if(levels.length){const done=levels.filter(x=>x.claimed),next=levels.find(x=>!x.claimed);body='<section class="panel player-level-achievement"><div class="row"><h3>玩家升級成就</h3><span>'+done.length+'／10</span></div><p>'+(next?'下個目標：首次達 '+next.goal+' 級（目前 '+next.value+'／'+next.goal+'）':'首次 10～100 級成就全部完成')+'</p><p>每 10 級首次達成，玩家碎片 +10，自動入帳。</p><details><summary>已完成的成就（'+done.length+'）</summary>'+(done.length?done.map(x=>'<p>首次達 '+x.goal+' 級 · 玩家碎片 +10 · 已入帳</p>').join(''):'<p>尚未完成等級成就。</p>')+'</details></section>'+body;}}
