 function claimReward(id){
  // 所有餘額、資格與逐筆紀錄合併成一次寫入，失敗時整批不入帳。
  try{const next=JSON.parse(localStorage.getItem(key)||JSON.stringify(state));next.mode=state.mode;next.unlocks??=state.unlocks;ProgressRewards.init(next);
   const ids=id==='*'?ProgressRewards.rows(next).filter(x=>!x.claimed&&x.value>=x.goal).map(x=>x.id):[id];
   const earned=ids.map(x=>ProgressRewards.claim(next,x)).filter(Boolean);
   if(!earned.length){state=next;render();toast('目前沒有可領取的獎勵。');return;}
   next.page='rewards';localStorage.setItem(key,JSON.stringify(next));state=next;render();
   const coins=earned.reduce((n,x)=>n+x.coins,0),diamonds=earned.reduce((n,x)=>n+x.diamonds,0);
   toast('已領取 '+earned.length+' 項：'+[earned.some(x=>x.attributeCard)?'自由屬性分配卡 ×'+earned.reduce((n,x)=>n+(x.attributeCard||0),0):'',earned.some(x=>x.attributeCardLow)?'自由屬性卡（低） ×'+earned.reduce((n,x)=>n+(x.attributeCardLow||0),0):'',earned.some(x=>x.chestCount)?'二級寶箱 ×'+earned.reduce((n,x)=>n+(x.chestCount||0),0):'',earned.some(x=>x.playerFragments)?'玩家碎片 +'+earned.reduce((n,x)=>n+(x.playerFragments||0),0):'',coins?'金幣 +'+coins:'',diamonds?'鑽石 +'+diamonds:'',earned.flatMap(x=>x.letters||[]).length?'字卡：'+earned.flatMap(x=>x.letters||[]).join('、'):''].filter(Boolean).join('、')+'。');
  }catch{toast('領取未完成：無法保存獎勵，請稍後重試。');}
 }
