 if(a==='saveTeam'){if(draft.slots[5]&&!StrategyPoints.canAppoint(draft.slots[5])){toast('軍師需智力65以上，請替換或移除目前人選。');return;}try{draft.slots=cleanSlots(draft.slots);draft.itemShortcuts=BattleShortcuts.slots(state,state.mode,draft);const latest=JSON.parse(localStorage.getItem(key)||JSON.stringify(state));latest.teams??={};latest.teams[teamKey()]=JSON.parse(JSON.stringify(draft));latest.mode=state.mode;latest.storyFaction=state.storyFaction;latest.page=taskReturn?'rewards':'armory';ProgressRewards.sync(latest);localStorage.setItem(key,JSON.stringify(latest));state=latest;draft=null;page=latest.page;taskReturn=false;rewardTab='task';render();toast('隊伍與五格道具配置已保存。');}catch{toast('配置尚未保存，請重試。');}return;}if(a==='cancelTeam'){draft=null;page='armory';render();toast('已還原保存的配置。');return;}if(a==='discard'){draft=null;close();if(b.dataset.next.startsWith('mode:'))setMode(b.dataset.next.slice(5));else navigate(b.dataset.next);return;}if(a==='storyFaction'){state.storyFaction=b.dataset.faction;state.libraryFaction=b.dataset.faction;save();render();return;}
 if(a==='help'){modal('操作說明','<p>散字也能戰鬥；組成武將後取得更完整的能力。</p><p>七格隊伍分為五將、軍師與運糧。系統補入本場七將，不填整備空格。</p><p>陣型依必要人選上場啟動；軍師提供計策值；運糧增加開局軍糧。兩者仍可招募部署，上場後技能與羈絆照常生效。</p><p>這是規則查閱，不是首次教學入口，沒有教學獎勵。</p>');return;}
