 function setMode(mode){draft=null;state.mode=mode;if(mode==='story'&&state.storyFaction)state.libraryFaction=state.storyFaction;if(page==='team')page='armory';save();render();}
 $('content').addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(b&&!b.disabled)act(b.dataset.a,b);});$('modalBody').addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(b&&!b.disabled)act(b.dataset.a,b);});$('closeModal').onclick=close;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.mode===state.mode)return;if(teamDraftChanged()){modal('切換模式？','<p>未確認的隊伍調整會取消，兩種模式的已保存配置互不影響。</p><div class="actions">'+btn('繼續編輯','close')+btn('取消修改並切換','discard',`data-next="mode:${b.dataset.mode}"`,'confirm')+'</div>');}else setMode(b.dataset.mode);});
 function renderGM(){$('toast').hidden=true;clearTimeout(toastTimer);document.querySelector('.app').classList.add('gm-testing');document.querySelector('.app').classList.remove('training-active');$('nav').hidden=true;$('modebar').hidden=true;$('settings').textContent='GM';$('content').innerHTML='<div class="gm-tools"><b>GM教學測試</b>'+btn('重回教學首頁','gmTutorial')+btn('返回原進度','gmReturn')+btn('關閉GM','gmOff')+'</div><iframe class="gm-preview" title="GM教學測試" src="主介面流程預覽.html?gmTutorial=1"></iframe>';}
 function openSettings(){modal('設定與進度',`<section class="panel"><h3>背景音樂</h3><label><input id="musicEnabled" type="checkbox" ${window.GameMusic?.state.enabled!==false?'checked':''}> 播放音樂</label><label for="musicVolume">音量</label><input id="musicVolume" type="range" min="0" max="1" step="0.05" value="${window.GameMusic?.state.volume??.35}"></section><p>進度保存在此裝置。換手機或加入主畫面前，請先匯出完整備份；不會自動同步到其他裝置。</p>${window.APP_VERSION?'':gmSandbox?'<p>目前為GM教學測試，請使用外層按鈕返回原進度。</p>':gmEnabled?'<section class="panel"><h3>GM模式 · 已開啟</h3><p>可重新查看教學首頁及完整演練，使用獨立測試進度。</p>'+btn('返回教學首頁（測試）','gmTutorial','','wide')+btn('關閉GM模式','gmOff','','wide')+'</section>':'<section class="panel"><h3>GM模式 · 已關閉</h3><label for="gmAccount">帳號</label><input id="gmAccount" class="search" autocomplete="username"><label for="gmPassword">密碼</label><input id="gmPassword" class="search" type="password" autocomplete="current-password"><p id="gmError" role="alert"></p>'+btn('開啟GM模式','gmLogin','','wide')+'</section>'}<div class="panel"><h3>進度管理</h3><p id="offlineSummary">${esc(window.GameOffline?.summary()||"本機檔案可直接離線使用")}</p><p><a href="章節下載.html">章節下載／離線準備</a></p>${btn('完整存檔備份／恢復','fullBackup','','wide')}<p>目前版本：${esc(window.APP_VERSION||'本機開發版')}。連線時自動檢查，回主城閒置後自動更新。</p></div>${btn('操作說明','help','','wide')}`);}
 $('settings').onclick=openSettings;
 window.addEventListener('storage',e=>{if(e.key===VillageHiddenItems.key){if(page==='bag')renderBag();return;}if(e.key!==key||!e.newValue)return;try{const latest=JSON.parse(e.newValue),keepDraft=teamDraftChanged();if(latest.teams){state.teams=latest.teams;if(draft&&!keepDraft)draft=JSON.parse(JSON.stringify(currentTeam()));}if(latest.playerOfficer){state.playerOfficer=latest.playerOfficer;PlayerOfficer.register(state);}if(latest.playerBattleReceipts)state.playerBattleReceipts=latest.playerBattleReceipts;if(latest.playerBubbleFirst)state.playerBubbleFirst=true;if(latest.battleItems)state.battleItems=latest.battleItems;if(latest.chests)state.chests=latest.chests;if(latest.bubbleTraining)state.bubbleTraining=latest.bubbleTraining;if(latest.rewards)state.rewards=latest.rewards;state.equipment=latest.equipment||{};if(equipmentView&&$('modal').open){if(equipmentView.kind==='hero')showEquipment(equipmentView.name);else if(equipmentView.kind==='slot')showEquipmentSlot(equipmentView.name,equipmentView.slot);else showBagEquipment(equipmentView.id);}if(latest.storyItems)state.storyItems=latest.storyItems;if(latest.storyEvents)state.storyEvents=latest.storyEvents;if(latest.storyMorale)state.storyMorale=latest.storyMorale;if(latest.townLodging)state.townLodging=latest.townLodging;if(latest.strategyPoints)state.strategyPoints=latest.strategyPoints;updateWallet();if(page==='rewards')renderRewards();if(page==='bag')renderBag();if(page==='armory'||page==='team')renderTeam();}catch{}});
 window.addEventListener('message',e=>{if(e.source!==$('tutorialFrame')?.contentWindow||state.tutorial.status!=='progress')return;const k=e.data?.kind;if(!['tutorial-progress','tutorial-leave','tutorial-completed'].includes(k))return;let checkpoint;try{checkpoint=JSON.parse(localStorage.getItem(trainingKey));}catch{}if(k==='tutorial-completed'){if(checkpoint?.engine!=='shared-battle-v2'||!checkpoint?.complete||checkpoint.stage!==3||checkpoint.history?.length!==4||!checkpoint.history.every(x=>x===true))return;state.tutorial={status:'completed',step:3,reward:'earned-pending',engine:1};state.mode='story';state.storyFaction='蜀';state.libraryFaction='蜀';teachVisible=false;page='home';save();render();modal('教學完成','<p>四段演練已完成！可領200 金幣＋隨機兩張蜀國青色字卡。請從主城「任務／成就」領取，獎勵只發放一次。</p>'+btn('前往領取獎勵','tutorialRewards','','confirm')+btn('稍後，先進主城','close'));return;}state.tutorial.step=checkpoint?.stage||0;save();if(k==='tutorial-leave'){teachVisible=false;render();}});
 if(new URLSearchParams(location.search).get('trainingXP')==='1'&&state.mode==='story'){page='library';tab='letters';}
